import React, { useState, useEffect } from "react";
import Map from "./Map";

function AdminPanel({
    plants,
    onAdd,
    onEdit,
    onDelete,
    addMode,
    setAddMode,
    pendingCoords,
    setPendingCoords,
    children
}) {
    const [editing, setEditing] = useState(null);
    const [form, setForm] = useState({
        id: "",
        name: "",
        image: "",
        x: "",
        y: "",
        shortDescription: "",
        fullDescription: "",
    });

    // Для передачи координат при редактировании
    const handleMarkerDrag = (coords) => {
        setForm(f => ({
            ...f,
            x: coords.x,
            y: coords.y,
        }));
    };

    useEffect(() => {
        if (pendingCoords) {
            setForm((f) => ({
                ...f,
                x: pendingCoords.x,
                y: pendingCoords.y,
            }));
        }
    }, [pendingCoords]);

    const handleEditClick = (plant) => {
        setEditing(plant.id);
        setPendingCoords(null);
        setForm(plant);
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (editing) {
            onEdit(form);
        } else {
            onAdd({ ...form, id: Date.now().toString() });
        }
        setForm({
            id: "",
            name: "",
            image: "",
            x: "",
            y: "",
            shortDescription: "",
            fullDescription: "",
        });
        setEditing(null);
        setPendingCoords(null);
    };

    const handleAddMode = () => {
        setAddMode(true);
        setPendingCoords(null);
        setForm({
            id: "",
            name: "",
            image: "",
            x: "",
            y: "",
            shortDescription: "",
            fullDescription: "",
        });
    };

    return (
        <div style={{ padding: 20 }}>
            <h2>Админ-панель</h2>
            <button onClick={handleAddMode} disabled={addMode}>
                {addMode ? "Кликните на карту" : "Добавить завод на карту"}
            </button>

            {addMode && (
                <div style={{ margin: "16px 0", border: "2px dashed #aaa" }}>
                    <p>Кликните на карту для выбора координат расположения завода.</p>
                    {children}
                </div>
            )}

            {(pendingCoords || editing) && (
                <div>
                    <Map
                        plants={plants}
                        onMarkerClick={() => { }}
                        editingPlant={editing ? form : null}
                        onMarkerDrag={handleMarkerDrag}
                        adminEditMode={!!editing}
                    />
                    <form onSubmit={handleSubmit} style={{ marginTop: 16 }}>
                        <input
                            placeholder="Название"
                            value={form.name}
                            onChange={(e) => setForm({ ...form, name: e.target.value })}
                            required
                        />
                        <input
                            placeholder="Ссылка на картинку"
                            value={form.image}
                            onChange={(e) => setForm({ ...form, image: e.target.value })}
                            required
                        />
                        <input
                            placeholder="X (0-100%)"
                            type="number"
                            value={form.x}
                            onChange={(e) => setForm({ ...form, x: Number(e.target.value) })}
                            required
                            min="0"
                            max="100"
                        />
                        <input
                            placeholder="Y (0-100%)"
                            type="number"
                            value={form.y}
                            onChange={(e) => setForm({ ...form, y: Number(e.target.value) })}
                            required
                            min="0"
                            max="100"
                        />
                        <input
                            placeholder="Краткое описание"
                            value={form.shortDescription}
                            onChange={(e) =>
                                setForm({ ...form, shortDescription: e.target.value })
                            }
                            required
                        />
                        <textarea
                            placeholder="Полное описание"
                            value={form.fullDescription}
                            onChange={(e) =>
                                setForm({ ...form, fullDescription: e.target.value })
                            }
                            required
                        />
                        <button type="submit">{editing ? "Сохранить" : "Добавить"}</button>
                        <button
                            type="button"
                            onClick={() => {
                                setEditing(null);
                                setPendingCoords(null);
                            }}
                        >
                            Отмена
                        </button>
                    </form>
                </div>
            )}

            <h3>Список заводов</h3>
            <ul>
                {plants.map((plant) => (
                    <li key={plant.id}>
                        <b>{plant.name}</b>
                        <button onClick={() => handleEditClick(plant)}>Редактировать</button>
                        <button onClick={() => onDelete(plant.id)}>Удалить</button>
                    </li>
                ))}
            </ul>
        </div>
    );
}

export default AdminPanel;
